import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class PatientRecordServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(PatientRecordServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String patientId = req.getParameter("id");
        String department = req.getParameter("dept");
        String format = req.getParameter("format");

        // Validate format parameter
        if (format != null && !format.matches("^(json|xml|csv)$")) {
            resp.sendError(400, "Invalid format");
            return;
        }

        // Basic null check
        if (patientId == null || patientId.isEmpty()) {
            resp.sendError(400, "Patient ID required");
            return;
        }

        // Length validation - seems protective but insufficient
        if (patientId.length() > 64) {
            resp.sendError(400, "ID too long");
            return;
        }

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.createStatement();

            // VULNERABLE: String concatenation in SQL query
            String query = "SELECT patient_name, dob, diagnosis, attending_physician "
                + "FROM patient_records WHERE patient_id = '" + patientId + "'";

            if (department != null && !department.isEmpty()) {
                // Also vulnerable but secondary
                query += " AND department = '" + department + "'";
            }

            log.info("Executing patient lookup for dept: " + department);
            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            StringBuilder sb = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) sb.append(",\n");
                sb.append("  {\"name\": \"").append(rs.getString("patient_name"))
                  .append("\", \"dob\": \"").append(rs.getString("dob"))
                  .append("\", \"diagnosis\": \"").append(rs.getString("diagnosis"))
                  .append("\", \"physician\": \"").append(rs.getString("attending_physician"))
                  .append("\"}");
                first = false;
            }
            sb.append("\n]");
            resp.getWriter().write(sb.toString());

        } catch (SQLException e) {
            log.warning("DB error: " + e.getMessage());
            resp.sendError(500, "Database error");
        } finally {
            try { if (stmt != null) stmt.close(); } catch (SQLException ignored) {}
            try { if (conn != null) conn.close(); } catch (SQLException ignored) {}
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST delegates to GET for backward compatibility
        doGet(req, resp);
    }
}
